def choose_move(observation):
    # Defensive access to observation fields with default values
    arena = observation.get('arena', [])
    agent_pos = observation.get('agent', {}).get('position', (0, 0))
    width = len(arena[0]) if arena else 0
    height = len(arena)

    # Helper functions
    def get_cell(x, y):
        if 0 <= y < height and 0 <= x < width:
            return arena[y][x]
        return None

    def is_resource(x, y):
        cell = get_cell(x, y)
        return cell == 'R'

    def is_enemy(x, y):
        cell = get_cell(x, y)
        return cell == 'E'

    def is_territory(x, y):
        cell = get_cell(x, y)
        return cell == 'T'

    # Current agent position
    x, y = agent_pos

    # Generate possible moves with their coordinates
    moves = {
        'up':    (x, y - 1),
        'down':  (x, y + 1),
        'left':  (x - 1, y),
        'right': (x + 1, y),
        'stay':  (x, y)
    }

    # Function to check if move keeps within bounds and is not blocked
    def is_valid_move(pos):
        px, py = pos
        if 0 <= px < width and 0 <= py < height:
            cell = get_cell(px, py)
            return cell != 'W'  # assume 'W' represents wall/blocked
        return False

    # Find resource cells adjacent
    resource_moves = []
    for dir_name, (nx, ny) in moves.items():
        if is_resource(nx, ny):
            resource_moves.append((dir_name, (nx, ny)))

    # Pursuit: check for enemies nearby (within 1 move)
    enemy_moves = []
    for dir_name, (nx, ny) in moves.items():
        if is_enemy(nx, ny):
            enemy_moves.append((dir_name, (nx, ny)))

    # Territory control: move towards known territory
    territory_moves = []
    for dir_name, (nx, ny) in moves.items():
        if is_territory(nx, ny):
            territory_moves.append((dir_name, (nx, ny)))

    # Prioritize resource collection
    if resource_moves:
        for dir_name, (nx, ny) in resource_moves:
            if is_valid_move((nx, ny)):
                if dir_name != 'stay':
                    return {'up': [0, -1], 'down': [0, 1], 'left': [-1, 0], 'right': [1, 0], 'stay': [0, 0]}[dir_name]
                           )
        # If resource is adjacent but blocked, consider staying
        return [0, 0]

    # Pursue enemy if nearby
    if enemy_moves:
        for dir_name, (nx, ny) in enemy_moves:
            if is_valid_move((nx, ny)):
                return {'up': [0, -1], 'down': [0, 1], 'left': [-1, 0], 'right': [1, 0], 'stay': [0, 0]}[dir_name]
                       )
        # If enemy adjacent but blocked, stay
        return [0, 0]

    # Move towards territory if known
    if territory_moves:
        for dir_name, (nx, ny) in territory_moves:
            if is_valid_move((nx, ny)):
                return {'up': [0, -1], 'down': [0, 1], 'left': [-1, 0], 'right': [1, 0], 'stay': [0, 0]}[dir_name]
                       )
        # If territory move blocked, stay
        return [0, 0]

    # Default: move randomly to any valid direction
    for dir_name in ['up', 'down', 'left', 'right']:
        nx, ny = moves[dir_name]
        if is_valid_move((nx, ny)):
            return {'up': [0, -1], 'down': [0, 1], 'left': [-1, 0], 'right': [1, 0]}[dir_name]
                   )

    # No valid moves; stay
    return [0, 0]
